int check_file_access(string path, string func) {
    if (!stringp(path)) {
        return 0;
    }
    if (strsrch(path, "/secure/") == 0 || strsrch(path, "/adm/") == 0) {
        return 0;
    }
    return 1;
}

int parse_command_verb(string verb) {
