int extract_second_int(string line) {
    int score;
    string rest;

    if (!stringp(line)) {
        return 0;
    }
    if (sscanf(line, "ID: %*d SCORE: %d%s", score, rest) == 3 && rest == "") {
        return score;
    }
    return 0;
}

