// Simulation of master::compile_object() for virtual map paths.

#define TEMPLATE_OB "/single/void"

object compile_object(string file) {
  string sx, sy, rest;

  if (!stringp(file)) {
    return 0;
  }
  if (sscanf(file, "/d/virtual/map_%(-?[0-9]+)_%(-?[0-9]+)%s", sx, sy, rest) != 3 ||
      rest != "") {
    return 0;
  }
  if (file_size(TEMPLATE_OB + ".lpc") > 0 || file_size(TEMPLATE_OB + ".c") > 0) {
    return clone_object(TEMPLATE_OB);
  }
  return clone_object(__FILE__);
}
